definition.script:
pipeline{
    agent{
        label "jenkins-agent"
    }
    tools {
        jfrog "my-jfrog-cli"
        gradle "my-gradle"
    }
    environment {
        SERVICES_LIST = "webapi,webui"
        ARTIFACTORY_VIRTUAL_REPO = "hands-on-virtual"

        MYSQL_CONTAINER = "zap-mysql"
		ZAP_CONTAINER_UI = "zap-scan-ui-${BUILD_NUMBER}"
		ZAP_CONTAINER_API = "zap-scan-api-${BUILD_NUMBER}"
        CONTAINER_NETWORK = "intra-net"

        GIT_REPO_HANDSON_PREFIX = "http://gitlab:13000/my-hands-on-group/webapp-"
        GIT_REPO_WEBAPP_ORIGIN = "https://github.com/Toshiharu-Konuma-sti/hands-on-rollingdice-webapp.git"

        JAR_FILE_PATTERN_API = "webapi/build/libs/apisl.handson.rollingdice.webapp.webapi-*-SNAPSHOT.jar"
        WEBAPP_PID_API = "webapp-webapi.pid"
        WEBAPP_LOG_API = "webapp-webapi.log"
        HEALTH_CHECK_URL_API = "http://localhost:8182/actuator/health"
        ZAP_TARGET_URL_API = "http://jenkins-agent:8182"
        ZAP_REPORT_NAME_API = "zap-api-scan-report-api.html"

        JAR_FILE_PATTERN_UI = "webui/build/libs/apisl.handson.rollingdice.webapp.webui-*-SNAPSHOT.jar"
        WEBAPP_PID_UI = "webapp-webui.pid"
        WEBAPP_LOG_UI = "webapp-webui.log"
        HEALTH_CHECK_URL_UI = "http://localhost:8181/actuator/health"
        ZAP_TARGET_URL_UI = "http://jenkins-agent:8181"
        ZAP_REPORT_NAME_UI = "zap-baseline-report-ui.html"

        TIMEOUT_EXP = 2
    }
    stages{
        stage("Clean up a local environment"){
            steps{
                echo "### START: clean up the cloned directoy"
                deleteDir()
            }
        }
        stage("Checkout a repository from GitLab"){
            steps{
                script {
                    def services = env.SERVICES_LIST.split(',')
                    services.each { serviceName ->
                        echo "--- Processing service: ${serviceName} ---"
                        def serviceGitUrl = "${env.GIT_REPO_HANDSON_PREFIX}${serviceName}.git"
                        dir(serviceName) {
                            echo "### [${serviceName}] START: Cloning repository from ${serviceGitUrl}"
                            git url: serviceGitUrl, branch: 'main'
                        }
                    }
                }
            }
        }
        stage("Build a repository"){
            steps{
                script {
                    def services = env.SERVICES_LIST.split(',')
                    services.each { serviceName ->
                        echo "--- Processing service: ${serviceName} ---"
                        dir(serviceName) {
                            echo "### [${serviceName}] START: Building with Gradle via Artifactory"
                            jf "gradle-config --repo-resolve ${ARTIFACTORY_VIRTUAL_REPO}"
                            jf "gradle assemble -x cyclonedxBom --info"
                        }
                    }
                }
            }
        }
        stage("Start up MySQL container") {
            steps {
                script {
                    dir("webapp-repo") {
                        echo "### START: Checkout MySQL configuration"
                        git url: GIT_REPO_WEBAPP_ORIGIN, branch: "main"

                        echo "### START: Creating MySQL container"
                        sh """
                            docker create --name ${MYSQL_CONTAINER} \\
                                -h zap-mysql \\
                                --network ${CONTAINER_NETWORK} \\
								--env-file .env-webapp-mysql \\
                                mysql:8.0
                        """

                        echo "### START: Copying configuration files to MySQL container"
                        sh "docker cp ./mysql/config/my.cnf ${MYSQL_CONTAINER}:/etc/mysql/conf.d/my.cnf"
                        sh "docker cp ./mysql/init/init.sql ${MYSQL_CONTAINER}:/docker-entrypoint-initdb.d/init.sql"
                    }

                    echo "### START: Starting MySQL container"
                    sh "docker start ${MYSQL_CONTAINER}"

                    echo "Waiting for MySQL server to start..."
                    timeout(time: TIMEOUT_EXP, unit: 'MINUTES') {
                        sh "until docker exec ${MYSQL_CONTAINER} mysqladmin ping -h 127.0.0.1 --silent; do echo 'Waiting for mysql...'; sleep 5; done"
                    }
                    echo "MySQL is up and running."
                }
            }
        }
        stage("Start up webapi process") {
            steps {
                script {
                    echo "### START: Starting WebApp API"
                    def jarFile_api = sh(script: "ls ${env.JAR_FILE_PATTERN_API}", returnStdout: true).trim()
                    if (jarFile_api.isEmpty()) {
                        error "JAR file not found with pattern: ${env.JAR_FILE_PATTERN_API}"
                    }
                    echo "Found JAR file: ${jarFile_api}"
                    sh """
                        export SPRING_PROFILES_ACTIVE=zap
                        nohup java -jar ${jarFile_api} \
                            --management.otlp.metrics.export.enabled=false \
                            --otel.sdk.disabled=true \
                            > ${env.WEBAPP_LOG_API} 2>&1 & echo \$! > ${env.WEBAPP_PID_API}
                    """
                    echo "Waiting for application api to start..."
                    timeout(time: TIMEOUT_EXP, unit: "MINUTES") {
                        sh "until curl -s -o /dev/null -w '%{http_code}' ${env.HEALTH_CHECK_URL_API} | grep -q '^[245]'; do echo 'Waiting for app...'; sleep 5; done"
                    }
                    echo "Application API is up and running."
                }
            }
        }
        stage("Start up webui process") {
            steps {
                script {
                    echo "### START: Starting WebApp UI"
                    def jarFile_ui = sh(script: "ls ${env.JAR_FILE_PATTERN_UI}", returnStdout: true).trim()
                    if (jarFile_ui.isEmpty()) {
                        error "JAR file not found with pattern: ${env.JAR_FILE_PATTERN_UI}"
                    }
                    echo "Found JAR file: ${jarFile_ui}"
                    sh """
                        export SPRING_PROFILES_ACTIVE=zap
                        nohup java -jar ${jarFile_ui} \
                            --management.otlp.metrics.export.enabled=false \
                            --otel.sdk.disabled=true \
                            > ${env.WEBAPP_LOG_UI} 2>&1 & echo \$! > ${env.WEBAPP_PID_UI}
                    """
                    echo "Waiting for application ui to start..."
                    timeout(time: TIMEOUT_EXP, unit: 'MINUTES') {
                        sh "until curl -s -o /dev/null -w '%{http_code}' ${env.HEALTH_CHECK_URL_UI} | grep -q '^[245]'; do echo 'Waiting for app...'; sleep 5; done"
                    }
                    echo "Application UI is up and running."
                }
            }
        }
        stage("Run DAST on webui with OWASP ZAP") {
            steps {
                script {
                    echo "### START: DAST scan with OWASP ZAP Docker container"
                    sh 'id'
                    def jenkinsUser = sh(script: "id -u", returnStdout: true).trim()
                    def jenkinsGroup = sh(script: "id -g", returnStdout: true).trim()
                    try {
                        sh """
                            docker run --name ${ZAP_CONTAINER_UI} --network ${CONTAINER_NETWORK} \\
                                -w /zap/wrk \\
                                -u ${jenkinsUser}:${jenkinsGroup} \\
                                --memory=1536m --memory-swap=1536m \\
                                ghcr.io/zaproxy/zaproxy:stable zap-baseline.py \\
                                    -t ${env.ZAP_TARGET_URL_UI} \\
                                    -r ${env.ZAP_REPORT_NAME_UI} -l WARN -d \\
                                    -z "-Xmx768m -silent -config scanner.delayInMs=500 -config spider.threadCount=1"
                        """
                    } catch (e) {
                        echo "DAST scan to webui found warnings, but proceeding. Marking build as UNSTABLE."
                        currentBuild.result = 'UNSTABLE'
                    } finally {
                        echo "Copying '${env.ZAP_REPORT_NAME_UI}' from container '${ZAP_CONTAINER_UI}' to workspace..."
                        sh "docker cp ${ZAP_CONTAINER_UI}:/zap/wrk/${env.ZAP_REPORT_NAME_UI} . || true"
                        containerId = sh(script: "docker ps -a -q --filter 'name=${ZAP_CONTAINER_UI}'", returnStdout: true).trim()
                        if (containerId) {
                            echo "Found existing container '${ZAP_CONTAINER_UI}' (${containerId}). Cleaning it up..."
                            sh "docker rm -f ${ZAP_CONTAINER_UI}"
                        }
                    }
                }
            }
            post {
                always {
                    script {
                        echo "### STARt: archiving and publishing for webui"
                        if (fileExists(ZAP_REPORT_NAME_UI)) {
                            echo "Archiving artifacts..."
                            archiveArtifacts artifacts: "${env.ZAP_REPORT_NAME_UI}, ${env.WEBAPP_LOG_UI}", allowEmptyArchive: false
                            echo "Publishing DAST report..."
                            publishHTML(
                                allowMissing: false,
                                alwaysLinkToLastBuild: true,
                                keepAll: true,
                                reportDir: ".",
                                reportFiles: "${env.ZAP_REPORT_NAME_UI}",
                                reportName: "DAST Scan Report (webui)"
                            )
                        }
                    }
                }
            }
        }
        stage("Run DAST on webapi with OWASP ZAP") {
            steps {
                script {
                    echo "### START: DAST scan with OWASP ZAP Docker container"
                    sh "id"
                    def jenkinsUser = sh(script: "id -u", returnStdout: true).trim()
                    def jenkinsGroup = sh(script: "id -g", returnStdout: true).trim()
                    try {
                        echo "START: Creaing OWASP Zap container"
                        sh """
                            docker create --name ${ZAP_CONTAINER_API} --network ${CONTAINER_NETWORK} \\
                                -w /zap/wrk/ \\
                                -u ${jenkinsUser}:${jenkinsGroup} \\
                                --memory=1536m --memory-swap=1536m \\
                                ghcr.io/zaproxy/zaproxy:stable zap-api-scan.py \\
                                    -t ${env.ZAP_TARGET_URL_API}/v3/api-docs -f openapi \\
                                    -r ${env.ZAP_REPORT_NAME_API} -l WARN -d \\
                                    -z "-Xmx768m -silent -config scanner.delayInMs=500 -config spider.threadCount=1 -config ascan.scanner.defaultPolicy.attackStrength=LOW -config ascan.scanner.defaultPolicy.alertThreshold=HIGH"
                        """
                        echo "START: Starting OWASP Zap container"
                        sh "docker start -a ${ZAP_CONTAINER_API}"
                    } catch (e) {
                        echo "DAST scan to webapi found warnings, but proceeding. Marking build as UNSTABLE."
                        currentBuild.result = "UNSTABLE"
                    } finally {
                        echo "Copying '${env.ZAP_REPORT_NAME_API}' from container '${ZAP_CONTAINER_API}' to workspace..."
                        sh "docker cp ${ZAP_CONTAINER_API}:/zap/wrk/${env.ZAP_REPORT_NAME_API} . || true"
                        containerId = sh(script: "docker ps -a -q --filter 'name=${ZAP_CONTAINER_API}'", returnStdout: true).trim()
                        if (containerId) {
                            echo "Found existing container '${ZAP_CONTAINER_API}' (${containerId}). Cleaning it up..."
                            sh "docker rm -f ${ZAP_CONTAINER_API}"
                        }
                    }
                }
            }
            post {
                always {
                    script {
                        echo "### STARt: archiving and publishing for webapi"
                        if (fileExists(ZAP_REPORT_NAME_API)) {
                            echo "Archiving artifacts..."
                            archiveArtifacts artifacts: "${env.ZAP_REPORT_NAME_API}, ${env.WEBAPP_LOG_API}", allowEmptyArchive: false
                            echo "Publishing DAST report..."
                            publishHTML(
                                allowMissing: false,
                                alwaysLinkToLastBuild: true,
                                keepAll: true,
                                reportDir: ".",
                                reportFiles: "${env.ZAP_REPORT_NAME_API}",
                                reportName: "DAST Scan Report (webapi)"
                            )
                        }
                    }
                }
            }
        }
    }
    post{
        always{
            echo "======== always ========"
            script {

                echo "Destroying MySQL Container..."
                def containerId = sh(script: "docker ps -a -q --filter 'name=${MYSQL_CONTAINER}'", returnStdout: true).trim()
                if (containerId) {
                    echo "Found existing container '${MYSQL_CONTAINER}' (${containerId}). Cleaning it up..."
                    sh "docker rm -f ${MYSQL_CONTAINER} || true"
                }

                echo "Stopping application..."
                if (fileExists(env.WEBAPP_PID_API)) {
                    sh "kill `cat ${env.WEBAPP_PID_API}` || true"
                }

                echo "Stopping application..."
                if (fileExists(env.WEBAPP_PID_UI)) {
                    sh "kill `cat ${env.WEBAPP_PID_UI}` || true"
                }

            }
        }
        success{
            echo "======== pipeline executed successfully ========"
        }
        failure{
            echo "======== pipeline execution failed========"
        }
    }
}
